-- Name: fn_validar_ruc_modulo11(character varying); Type: FUNCTION; Schema: public
--
CREATE OR REPLACE FUNCTION public.fn_validar_ruc_modulo11(p_ruc character varying) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
AS $$
DECLARE
    v_factores integer[] := ARRAY[5, 4, 3, 2, 7, 6, 5, 4, 3, 2];
    v_suma integer := 0;
    v_residuo integer;
    v_digito_verificador integer;
    v_digito_esperado integer;
    i integer;
BEGIN
    IF LENGTH(p_ruc) <> 11 OR p_ruc !~ '^[0-9]+$' THEN
        RETURN FALSE;
    END IF;
    IF SUBSTRING(p_ruc, 1, 2) NOT IN ('10', '15', '17', '20') THEN
        RETURN FALSE;
    END IF;
    FOR i IN 1..10 LOOP
        v_suma := v_suma + (SUBSTRING(p_ruc, i, 1)::integer * v_factores[i]);
    END LOOP;
    v_residuo := v_suma % 11;
    v_digito_verificador := 11 - v_residuo;
    IF v_digito_verificador = 10 THEN
        v_digito_esperado := 0;
    ELSIF v_digito_verificador = 11 THEN
        v_digito_esperado := 1;
    ELSE
        v_digito_esperado := v_digito_verificador;
    END IF;
    RETURN v_digito_esperado = SUBSTRING(p_ruc, 11, 1)::integer;
END;
$$;

